package com.bank.interest.service;

import com.bank.interest.cache.CacheService;
import com.bank.interest.dto.*;
import com.bank.interest.fraud.FraudCheckService;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*;
import org.mockito.junit.jupiter.MockitoExtension;
import java.math.BigDecimal;
import java.util.Optional;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class InterestServiceTest {

    @Mock RateProviderService rateProvider;
    @Mock CacheService cacheService;

    @Test
    void shouldCalculateInterestWithoutFraudCheck() {
        // Dev environment: no FraudCheckService bean exists
        InterestService service = new InterestService(rateProvider, cacheService, Optional.empty());

        when(rateProvider.getCurrentRate("FD")).thenReturn(new BigDecimal("8.50"));
        when(rateProvider.getSourceName()).thenReturn("MOCK");
        when(cacheService.getCacheType()).thenReturn("In-Memory");

        InterestResponse response = service.calculate(
            new InterestRequest("SAV2001", new BigDecimal("100000"), 12));

        assertThat(response.interestRate()).isEqualByComparingTo("8.50");
        assertThat(response.totalInterest()).isEqualByComparingTo("8500.00");
        assertThat(response.maturityAmount()).isEqualByComparingTo("108500.00");
        assertThat(response.rateSource()).isEqualTo("MOCK");
    }

    @Test
    void shouldRunFraudCheckWhenEnabled() {
        FraudCheckService fraudCheck = mock(FraudCheckService.class);
        when(fraudCheck.isSafe(anyString(), any())).thenReturn(true);

        InterestService service = new InterestService(rateProvider, cacheService, Optional.of(fraudCheck));
        when(rateProvider.getCurrentRate("FD")).thenReturn(new BigDecimal("7.25"));
        when(rateProvider.getSourceName()).thenReturn("LIVE");
        when(cacheService.getCacheType()).thenReturn("Redis");

        service.calculate(new InterestRequest("SAV2001", new BigDecimal("500000"), 24));

        verify(fraudCheck).isSafe("SAV2001", new BigDecimal("500000"));
    }
}
